module barrel_shifter(
    input [7:0] in,
    input [2:0] ctrl,
    output [7:0] out
);
// Parameter definitions
parameter NUM_STAGES = 3;
// Internal variables
reg [7:0] stage_out [0:NUM_STAGES-1];
integer i;
// Combinational logic for generating the stages of the barrel shifter
always @* begin
    stage_out[0] = in;
    for (i = 0; i < NUM_STAGES; i = i + 1) begin
        stage_out[i+1] = (ctrl[i]) ? stage_out[i] << (1 << i) : stage_out[i];
    end
end
// Output assignment
assign out = stage_out[NUM_STAGES];
endmodule
